# -----------------------------
# Geometry helpers
# -----------------------------

def clean(g):
    if g.is_empty:
        return g
    g = shapely.set_precision(g, grid_size=0.001)
    if not g.is_valid:
        g = shapely.make_valid(g)
    return g


def circle(x: float, y: float, r: float, resolution: int = 64):
    return Point(x, y).buffer(r, quad_segs=resolution)


def rounded_rect(xmin: float, ymin: float, xmax: float, ymax: float, r: float):
    if r <= 0:
        return box(xmin, ymin, xmax, ymax)
    core = box(xmin + r, ymin + r, xmax - r, ymax - r)
    return core.buffer(r, join_style='round')


def rings_of(g):
    if g.is_empty:
        return
    if isinstance(g, Polygon):
        yield g.exterior
        for ring in g.interiors:
            yield ring
    elif isinstance(g, MultiPolygon):
        for p in g.geoms:
            yield from rings_of(p)
    elif isinstance(g, GeometryCollection):
        for x in g.geoms:
            if isinstance(x, (Polygon, MultiPolygon)):
                yield from rings_of(x)


def polygons_of(g):
    if g.is_empty:
        return
    if isinstance(g, Polygon):
        yield g
    elif isinstance(g, MultiPolygon):
        for p in g.geoms:
            yield p
    elif isinstance(g, GeometryCollection):
        for x in g.geoms:
            if isinstance(x, Polygon):
                yield x
            elif isinstance(x, MultiPolygon):
                for p in x.geoms:
                    yield p


def tri_area2(coords):
    (x0, y0), (x1, y1), (x2, y2) = coords
    return (x1-x0)*(y2-y0) - (y1-y0)*(x2-x0)


def add_horizontal_surface(vertices, faces, geom, z: float, up: bool):
    geom = clean(geom)
    if geom.is_empty:
        return
    tris = shapely.constrained_delaunay_triangles(geom)
    for tri in getattr(tris, 'geoms', [tris]):
        if not isinstance(tri, Polygon) or tri.area < 1e-9:
            continue
        # CDT should respect boundaries, but guard against numerical leftovers.
        rp = tri.representative_point()
        if not geom.covers(rp):
            continue
        coords = list(tri.exterior.coords)[:3]
        if tri_area2(coords) < 0:
            coords = [coords[0], coords[2], coords[1]]
        if not up:
            coords = [coords[0], coords[2], coords[1]]
        idx = []
        for x, y in coords:
            idx.append(len(vertices))
            vertices.append([x, y, z])
        faces.append(idx)


def add_vertical_walls(vertices, faces, geom, z0: float, z1: float):
    """Add side walls for a single atomic cell.

    The diagonal is chosen from lexicographically ordered endpoints so two
    adjacent cells generate identical internal triangles, which can be removed.
    """
    geom = clean(geom)
    for ring in rings_of(geom):
        coords = list(ring.coords)
        for i in range(len(coords)-1):
            a = (float(coords[i][0]), float(coords[i][1]))
            b = (float(coords[i+1][0]), float(coords[i+1][1]))
            if abs(a[0]-b[0])+abs(a[1]-b[1]) < 1e-9:
                continue
            p, q = sorted([a, b])
            base = len(vertices)
            vertices.extend([
                [p[0], p[1], z0],
                [q[0], q[1], z0],
                [q[0], q[1], z1],
                [p[0], p[1], z1],
            ])
            faces.append([base, base+1, base+2])
            faces.append([base, base+2, base+3])


def layered_mesh(layers: Sequence[Tuple[float, float, Any]], name: str = '') -> trimesh.Trimesh:
    """Build a watertight 2.5D union from layer cross sections.

    All profile boundaries are polygonized into atomic planar cells. A prism is
    generated for every occupied cell/layer interval. Exact internal duplicate
    triangles are then removed. This avoids T-junctions when a channel reaches an
    exterior edge or when a raised feature starts on a larger lower profile.
    """
    from shapely.ops import polygonize

    layers = [(float(a), float(b), clean(g)) for a,b,g in layers if b > a and not g.is_empty]
    layers.sort(key=lambda x: x[0])
    if not layers:
        raise ValueError(f'No geometry for {name}')

    linework = unary_union([g.boundary for _,_,g in layers])
    cells = [clean(c) for c in polygonize(linework) if c.area > 1e-8]
    if not cells:
        raise ValueError(f'Polygonization produced no cells for {name}')

    vertices: List[List[float]] = []
    faces: List[List[int]] = []
    for cell in cells:
        rp = cell.representative_point()
        for z0, z1, g in layers:
            if g.covers(rp):
                add_horizontal_surface(vertices, faces, cell, z0, up=False)
                add_horizontal_surface(vertices, faces, cell, z1, up=True)
                add_vertical_walls(vertices, faces, cell, z0, z1)

    mesh = trimesh.Trimesh(vertices=np.asarray(vertices), faces=np.asarray(faces), process=False)
    mesh.merge_vertices(digits_vertex=5)
    mesh.remove_unreferenced_vertices()

    # Remove paired internal faces after the atomic-cell prisms are assembled.
    sorted_faces = np.sort(mesh.faces, axis=1)
    _, inverse, counts = np.unique(sorted_faces, axis=0, return_inverse=True, return_counts=True)
    keep = counts[inverse] == 1
    mesh.update_faces(keep)
    mesh.remove_unreferenced_vertices()
    trimesh.repair.fix_normals(mesh, multibody=True)
    mesh.metadata['name'] = name
    return mesh

def transform_geom(g, angle_deg=0.0, tx=0.0, ty=0.0):
    h = affinity.rotate(g, angle_deg, origin=(0,0), use_radians=False)
    h = affinity.translate(h, xoff=tx, yoff=ty)
    return clean(h)


def polyline_channel(points, width, cap='flat'):
    cap_style = 'flat' if cap == 'flat' else 'round'
    return clean(LineString(points).buffer(width/2, cap_style=cap_style, join_style='round'))


def module_outline(length=58.0, width=38.0, chamfer=4.0):
    L, W, c = length/2, width/2, chamfer
    pts = [(-L,-W),(L,-W),(L,W-c),(L-c,W),(-L,W)]
    return clean(Polygon(pts))


def module_pocket_outline(clear=0.2):
    # clearance is per side; preserve key chamfer and add clearance conservatively.
    L = P['module']['body_length_mm']/2 + clear
    W = P['module']['body_width_mm']/2 + clear
    c = P['module']['key_chamfer_mm'] + 0.15
    pts = [(-L,-W),(L,-W),(L,W-c),(L-c,W),(-L,W)]
    return clean(Polygon(pts))


def rotate_translate_module(g, direction: str):
    centers = {'E': (59.2,0,0), 'N': (0,59.2,90), 'W': (-59.2,0,180), 'S': (0,-59.2,-90)}
    tx,ty,a = centers[direction]
    return transform_geom(g,a,tx,ty)


def mesh_export(mesh: trimesh.Trimesh, path: Path):
    path.parent.mkdir(parents=True, exist_ok=True)
    mesh.export(path, file_type='stl')


def combine_meshes(meshes: Sequence[trimesh.Trimesh], translations: Sequence[Tuple[float,float,float]] | None = None):
    out=[]
    if translations is None:
        translations=[(0,0,0)]*len(meshes)
    for m,t in zip(meshes, translations):
        c=m.copy(); c.apply_translation(t); out.append(c)
    return trimesh.util.concatenate(out)

