def mic_insert_mesh(bore_d: float, name: str):
    bore=circle(0,0,bore_d/2,48)
    flange=clean(circle(0,0,15,64).difference(bore))
    neck=clean(circle(0,0,10.0,64).difference(bore))
    ridge=clean(circle(0,0,10.12,64).difference(bore))
    return layered_mesh([(0,2.4,flange),(2.4,4.4,neck),(4.4,4.9,ridge),(4.9,6.0,neck)],name)

