# -----------------------------
# Port plug
# -----------------------------
# P01's outer passage is a tapered plan-view diffuser: at the physical side
# plane x=105 mm its opening is ~14.8 mm wide, narrowing to 10.8 mm at
# 10 mm insertion depth and ~10.31 mm at 12 mm.  V1.0.0 incorrectly used a
# constant-width rectangular shaft and checked only the face width.  V1.0.1
# uses a true tapered shaft and validates the complete insertion envelope.

def chamfered_rect_coords(width: float, height: float, chamfer: float):
    w, h, c = width/2.0, height/2.0, min(chamfer, width/4.0, height/4.0)
    return [(-w+c,-h),(w-c,-h),(w,-h+c),(w,h-c),
            (w-c,h),(-w+c,h),(-w,h-c),(-w,-h+c)]


def tapered_port_plug_mesh() -> trimesh.Trimesh:
    flange_z = P['port_plug']['flange_thickness_mm']
    # The pull tab is coplanar with the flange so the part prints flange-down
    # without support; the tapered shaft then grows vertically from the bed.
    flange_main = rounded_rect(-11.5,-7.0,11.5,7.0,1.5)
    pull_tab = rounded_rect(-4.5,6.0,4.5,14.0,1.2)
    flange_prof = clean(unary_union([flange_main, pull_tab]))

    # (model z, width, height, corner chamfer).  In use the model z-axis is the
    # insertion axis.  z=flange_z is the port face; the highest/narrowest
    # section is inserted deepest.  Profiles follow the two linear tapers in
    # OUTER_CH with >=0.3 mm nominal clearance per side.
    prof_data = [
        (flange_z,       14.2, 7.4, 0.55),   # depth 0 mm
        (flange_z+10.0, 10.2, 7.3, 0.50),   # depth 10 mm
        (flange_z+11.4,  9.85,7.2, 0.45),   # depth 11.4 mm
        (flange_z+12.0,  9.2, 6.8, 0.40),   # lead-in tip at depth 12 mm
    ]
    profiles=[]
    for z,w,h,c in prof_data:
        coords=chamfered_rect_coords(w,h,c)
        profiles.append((z,coords,clean(Polygon(coords))))

    vertices: List[List[float]]=[]
    faces: List[List[int]]=[]

    # Flange bottom and outer walls.
    add_horizontal_surface(vertices,faces,flange_prof,0.0,up=False)
    add_vertical_walls(vertices,faces,flange_prof,0.0,flange_z)
    # Flange top, excluding the shaft footprint so the union has no internal cap.
    shaft_bottom=profiles[0][2]
    add_horizontal_surface(vertices,faces,clean(flange_prof.difference(shaft_bottom)),flange_z,up=True)

    # Loft the tapered shaft between equal-vertex-count chamfered rectangles.
    for (z0,c0,_),(z1,c1,_) in zip(profiles[:-1],profiles[1:]):
        n=len(c0)
        for i in range(n):
            j=(i+1)%n
            base=len(vertices)
            vertices.extend([[c0[i][0],c0[i][1],z0],
                             [c0[j][0],c0[j][1],z0],
                             [c1[j][0],c1[j][1],z1],
                             [c1[i][0],c1[i][1],z1]])
            faces.append([base,base+1,base+2])
            faces.append([base,base+2,base+3])
    add_horizontal_surface(vertices,faces,profiles[-1][2],profiles[-1][0],up=True)

    mesh=trimesh.Trimesh(vertices=np.asarray(vertices),faces=np.asarray(faces),process=False)
    mesh.merge_vertices(digits_vertex=5)
    mesh.remove_unreferenced_vertices()
    trimesh.repair.fix_normals(mesh,multibody=True)
    mesh.metadata['name']='P04_port_plug_tapered_v1_0_1'
    return mesh

