def svg_path_for_geom(g, flip_y=True):
    parts=[]
    for poly in polygons_of(g):
        rings=[poly.exterior]+list(poly.interiors)
        for ring in rings:
            coords=list(ring.coords)
            if not coords: continue
            x0,y0=coords[0]; y0=-y0 if flip_y else y0
            seg=[f'M {x0:.3f},{y0:.3f}']
            for x,y in coords[1:]:
                y=-y if flip_y else y
                seg.append(f'L {x:.3f},{y:.3f}')
            seg.append('Z')
            parts.append(' '.join(seg))
    return ' '.join(parts)

def write_svg(g,path:Path,margin=5):
    minx,miny,maxx,maxy=g.bounds
    w=maxx-minx+2*margin; h=maxy-miny+2*margin
    # y flipped, viewbox starts at -maxy
    vb_x=minx-margin; vb_y=-maxy-margin
    p=svg_path_for_geom(g,True)
    txt=f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w:.3f}mm" height="{h:.3f}mm" viewBox="{vb_x:.3f} {vb_y:.3f} {w:.3f} {h:.3f}">
  <path d="{p}" fill="none" stroke="black" stroke-width="0.2" fill-rule="evenodd"/>
</svg>\n'''
    path.write_text(txt,encoding='utf-8')

write_svg(gasket_B1_prof,SVG/'gasket_B1_symmetric_1to1.svg')
