# Validate the complete tapered P04 insertion envelope, not only the mouth.
def port_width_at_depth(depth_mm: float) -> float:
    x=105.0-depth_mm
    cut=OUTER_CH.intersection(LineString([(x,-100.0),(x,100.0)]))
    if cut.is_empty:
        return 0.0
    ys=[]
    geoms=[cut] if cut.geom_type=='LineString' else list(cut.geoms)
    for g in geoms:
        ys.extend([float(v[1]) for v in g.coords])
    return max(ys)-min(ys)

plug_depths=np.asarray([0.0,10.0,11.4,12.0])
plug_widths=np.asarray([14.2,10.2,9.85,9.2])
def plug_width_at_depth(depth_mm: float) -> float:
    return float(np.interp(depth_mm,plug_depths,plug_widths))

