def scene_for(encoded=True):
    sc=trimesh.Scene()
    base=base_mesh.copy(); base.visual.face_colors=[170,170,180,255]; sc.add_geometry(base,node_name='base')
    mapping=[('N',module_meshes['A_short_straight']),('E',module_meshes['B_long_serpentine'] if encoded else module_meshes['A_short_straight']),
             ('S',module_meshes['C_straight_short_stub'] if encoded else module_meshes['A_short_straight']),('W',module_meshes['D_dogleg_long_stub'] if encoded else module_meshes['A_short_straight'])]
    dirs={'E':(0,59.2,0),'N':(90,0,59.2),'W':(180,-59.2,0),'S':(-90,0,-59.2)}
    colors={'N':[220,80,80,255],'E':[80,150,230,255],'S':[90,190,110,255],'W':[220,170,70,255]}
    for d,m in mapping:
        c=m.copy(); a,tx,ty=dirs[d]
        c.apply_transform(trimesh.transformations.rotation_matrix(math.radians(a),[0,0,1]))
        c.apply_translation([tx,ty,2.4])
        c.visual.face_colors=colors[d]; sc.add_geometry(c,node_name=f'module_{d}')
    lid=lid_mesh.copy(); lid.apply_translation([0,0,24]); lid.visual.face_colors=[210,210,220,180]; sc.add_geometry(lid,node_name='lid_exploded')
    return sc

