(SRC/'requirements.txt').write_text('numpy\nshapely>=2.1\ntrimesh\nmatplotlib\n',encoding='utf-8')

(STL/'README_UNITS_MM.txt').write_text('All STL coordinates are in millimetres. Do not import as inches.\n',encoding='utf-8')


